 const open=i=>{listScroll=dialog.scrollTop;current=i;viewing=true;grid.hidden=true;viewer.hidden=false;dialog.querySelector('.export-help').hidden=true;dialog.scrollTop=0;slides.scrollLeft=order.indexOf(i)*slides.clientWidth;update();};
 slides.addEventListener('scroll',()=>{if(!viewing||!slides.clientWidth)return;current=order[Math.max(0,Math.min(4,Math.round(slides.scrollLeft/slides.clientWidth)))];update();},{signal:session.signal});
