 dialog.querySelector('#export-back').onclick=()=>{if(viewing){viewing=false;viewer.hidden=true;grid.hidden=false;dialog.querySelector('.export-help').hidden=false;dialog.scrollTop=listScroll;update();}else{stop();dialog.close();}};
