 dialog.addEventListener('click',e=>{const link=e.target.closest('a[download]');if(!link?.href||e.defaultPrevented)return;state.downloadedExports=[...new Set([...(state.downloadedExports||[]),link.download])];persist();dialog.querySelectorAll('a[download]').forEach(a=>{if(a.href===link.href)a.classList.add('downloaded');});zipButton.classList.toggle('downloaded',state.downloadedExports.includes('Liwu-images.zip'));},{signal:session.signal});
 zipButton.onclick=async()=>{if(!blobs.every(Boolean))return;zipButton.disabled=true;const status=dialog.querySelector('#zip-status');status.textContent=tr('creatingZip');try{const blob=await makeZip(order.map(i=>({name:`Liwu-${files[i]}.png`,blob:blobs[i]})));if(session.signal.aborted)return;const url=URL.createObjectURL(blob);exportURLs.push(url);const link=dialog.querySelector('#zip-file');link.href=url;link.hidden=false;zipButton.classList.add('downloaded');status.textContent=tr('zipReady');link.click();}catch(err){console.error(err);if(!session.signal.aborted)status.textContent=tr('zipFailed');}finally{if(!session.signal.aborted)zipButton.disabled=false;}};
 dialog.addEventListener('close',()=>{if(dialog.open)return;stop();},{signal:session.signal});
 const generate=async i=>{const target=grid.querySelector(`[data-preview="${i}"]`),status=grid.querySelector(`[data-status="${i}"]`);status.textContent='';target.textContent=tr('loading');target.setAttribute('aria-busy','true');try{const {blob,preview}=await renderExportAsset(snapshot,i);if(session.signal.aborted)return;const url=URL.createObjectURL(blob);blobs[i]=blob;urls[i]=url;exportURLs.push(url);const previewURL=URL.createObjectURL(preview);exportURLs.push(previewURL);const im=new Image();im.alt=names[i];im.src=previewURL;await im.decode();if(session.signal.aborted)return;target.replaceChildren(im);target.disabled=false;target.onclick=()=>open(i);const link=grid.querySelector(`[data-file="${i}"]`);link.href=url;link.hidden=false;}catch(err){if(session.signal.aborted)return;console.error(err);target.textContent=tr('previewUnavailable');status.textContent=tr('imageLoadFailed');const retry=document.createElement('button');retry.type='button';retry.textContent=tr('retry');retry.onclick=()=>generate(i);status.append(retry);}finally{if(!session.signal.aborted){target.setAttribute('aria-busy','false');update();}}};
 update();dialog.scrollTop=0;(async()=>{for(const i of order){if(session.signal.aborted)break;await generate(i);}})();
